//! FFI binding crate for `kibo-kms-rest`.
//!
//! Exposes `zk_encrypt` / `zk_decrypt` over two ABI surfaces:
//!
//! - **`ffi-uniffi`** — uniffi proc-macro exports for Swift, Kotlin, Python,
//!   Go, Ruby, C bindings generated by `uniffi-bindgen`.
//! - **`ffi-wasm`** — `#[wasm_bindgen]` exports for browser and React Native
//!   JS SDKs (reqwest's `fetch` backend; single-threaded model).
//!
//! Provider selection is the same composable feature flag set as
//! `kibo-kms-rest`: enable one or more of `kms-aws`, `kms-gcp`, `kms-azure`,
//! `kms-vault`; the provider is chosen at call time from the runtime `provider`
//! field, so an all-providers build serves every provider from one artifact.
//!
//! # Strict-ZK invariant
//!
//! `zk_encrypt` accepts only `FfiPosture::Byok` and `FfiPosture::Hyok` —
//! `PlatformManaged` is structurally absent from the input type. The
//! `kms_cred` field is a customer KMS credential exclusively; no platform KEK
//! parameter exists or can be added.

#![forbid(unsafe_code)]
#![allow(clippy::doc_markdown)]
// FFI crate: public surface is the generated language bindings, not Rust rustdoc.
#![allow(missing_docs)]

// Provider `kms-*` features are additive and composable (mirrors kibo-kms-rest):
// one for a minimal client, all four for a build-all-providers artifact. The
// engine dispatches on the runtime `provider`; a build with zero providers
// rejects every call at runtime.

pub mod app_crypto;
pub mod engine;
pub mod envelope;
pub mod federate;
pub mod types;

// uniffi scaffolding must be in the crate root so UniFfiTag is defined at
// `crate::UniFfiTag`, which is where #[derive(uniffi::Record/Enum/Error)] on
// types in any submodule looks for it.
#[cfg(feature = "ffi-uniffi")]
uniffi::setup_scaffolding!();

#[cfg(feature = "ffi-uniffi")]
pub mod ffi_uniffi;

#[cfg(feature = "ffi-wasm")]
pub mod ffi_wasm;

pub use app_crypto::{app_crypto_open, app_crypto_seal};
pub use engine::{core_capabilities, zk_decrypt, zk_encrypt};
pub use types::{
    AppOpenInput, AppOpenOutput, AppSealInput, AppSealOutput, DecryptInput, DecryptOutput,
    EncryptInput, EncryptOutput, FfiAttestationTier, FfiCredential, FfiKeyRef, FfiOracleMode,
    FfiPosture, FfiPosturePolicy, FfiProviderConfig, FfiStrategy, KmsProvider,
    PostureViolationContext, ZkFfiError,
};
